export const getListFoodsUrl = (params?: ListFoodsParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : value.toString())
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/foods?${stringifiedParams}` : `/api/foods`
}

/**
 * @summary List famous foods, optionally filtered by city or province
 */
export const listFoods = async (params?: ListFoodsParams, options?: RequestInit): Promise<FoodItem[]> => {

  return customFetch<FoodItem[]>(getListFoodsUrl(params),
  {
    ...options,
    method: 'GET'


  }
);}





export const getListFoodsQueryKey = (params?: ListFoodsParams,) => {
    return [
    `/api/foods`, ...(params ? [params] : [])
    ] as const;
    }


export const getListFoodsQueryOptions = <TData = Awaited<ReturnType<typeof listFoods>>, TError = ErrorType<unknown>>(params?: ListFoodsParams, options?: { query?:UseQueryOptions<Awaited<ReturnType<typeof listFoods>>, TError, TData>, request?: SecondParameter<typeof customFetch>}
) => {

const {query: queryOptions, request: requestOptions} = options ?? {};

  const queryKey =  queryOptions?.queryKey ?? getListFoodsQueryKey(params);



    const queryFn: QueryFunction<Awaited<ReturnType<typeof listFoods>>> = ({ signal }) => listFoods(params, { signal, ...requestOptions });





   return  { queryKey, queryFn, ...queryOptions} as UseQueryOptions<Awaited<ReturnType<typeof listFoods>>, TError, TData> & { queryKey: QueryKey }
}

